data.query:
query andonRequestInventory($AndonRequestInventoryWhereInput:AndonRequestInventoryWhereInput!, $InventoryWhereInput:InventoryWhereInput!) {
  andonRequestInventory(where:$AndonRequestInventoryWhereInput) {
    edges {
      node {
        id
        andonRequestId
      }
    }
  }

	inventory(where:$InventoryWhereInput) {
    edges {
      node {
        id
        number
        productStrategyProcessId
        location {
          id
          name
        }
        quantity {
          value
          unit {
            id
            unitType {
              id
              label
            }
          }
        }
        inventoryStatus {
          active
          suspect
        }
      }
    }
  }

  andonStage(where:{inProcess:{_eq:true}}) {
    edges {
      node {
        id
      }
    }
  }
}

